insert into woerter (slug, wort, artikel, ipa, wortart, kategorie, definition, bedeutungen, beispiel) values
  ('ob-mazagran-owamaia-oda-maria-teresiana-in-de-wiina-kaffeeheisa-gibds-olle-drei', 'Ob Mazagran, Owamaia oda Maria Teresiana - in de Wiina Kaffeeheisa gibds olle drei!', '', '', '', 'Wiener Kaffeehaus-ABC', 'Ob Mazagran, Obermayer oder Maria Theresiana - in den Wiener Kaffeehäusern gibt''s alle drei!', '[{"kategorie": "wörtlich", "text": "\"Ob Mazagran, Obermayer oder Maria Theresiana - in den Wiener Kaffeehäusern gibt''s alle drei Kaffeespezialitäten!\"  2. Mazagran, Obermayer und Maria Theresiana – alle drei sind feste Größen im Wiener Kaffeehaus-Repertoire!  3. Im Wiener Kaffeehaus bekommt man Klassiker wie Mazagran, Obermayer und Maria Theresiana fast wie selbstverständlich serviert!"}]'::jsonb, ''),
  ('siassa-raam', 'siassa Raam', '', '', '', 'Wiener Küche & Gaumenfreuden', 'süßer Rahm', '[{"kategorie": "wörtlich", "text": "\"Süßrahm\" (vom mittelhochdeutschen \"roum\"=\"Milchrahm\")"}, {"kategorie": "allg.", "text": "Schlagsahne, [[Obers]] (\"das Obere der Milch\"), [[Schlagobers]], [[Schlagrahm]] (Rahmsorte, die sich zum Aufschlagen eignet und einen Fettgehalt von mindestens 30 % hat)"}]'::jsonb, 'I mog mein Kaffee aum liabstn mit an Schuss siassn Raam!'),
  ('i-mog-mein-kaffee-aum-liabstn-mit-an-schuss-siassn-raam', 'I mog mein Kaffee aum liabstn mit an Schuss siassn Raam!', '', '', '', 'Wiener Kaffeehaus-ABC', 'Ich mag meinen Kaffee am liebsten mit einem Schuss Süßrahm!', '[{"kategorie": "wörtlich", "text": "\"Ich mag meinen Kaffee am liebsten mit einem Schuss [[Obers]]!\"  2. Am besten schmeckt mir der Kaffee mit ein wenig Schlagsahne!  3. Ein Schuss Obers im Kaffee - und der Tag kann beginnen!"}]'::jsonb, 'siassa Raam'),
  ('a-gupfal-schloograam-aufn-kaffee-mea-brauchds-ned-zum-glicklichsei', 'A Gupfal Schloograam aufn Kaffee - mea brauchds ned zum Glicklichsei!', '', '', '', 'Wiener Kaffeehaus-ABC', 'Ein Gupferl Schlagrahm auf dem Kaffee – mehr braucht''s nicht zum Glücklichsein!', '[{"kategorie": "wörtlich", "text": "\"Ein Häubchen Schlagrahm auf dem Kaffee – mehr braucht es nicht zum Glücklichsein!\"  2. Ein zarter Sahnehauch auf dem Kaffee – und die Welt ist in Ordnung!  3. Ein weißes Krönchen auf dem schwarzen Gold – und der Tag ist gerettet! 8"}]'::jsonb, ''),
  ('i-nimm-mein-kaffee-mit-a-bissl-oowas-bitte', 'I nimm mein Kaffee mit a bissl Oowas, bitte!', '', '', '', 'Wiener Kaffeehaus-ABC', 'Ich nehme meinen Kaffee mit ein bissl Obers, bitte!', '[{"kategorie": "wörtlich", "text": "\"Ich nehme meinen Kaffee mit ein bisschen Sahne, bitte!\"  2. Ich hätte meinen Kaffee gerne mit einem Schuss Schlagobers, bitte!  3. Ich trinke meinen Kaffee am liebsten mit einem Hauch Obers!"}]'::jsonb, ''),
  ('oowas-gschbritzd', 'Oowas gschbritzd', '', '', '', 'Wiener Kaffeehaus-ABC', 'Obers gespritzt', '[{"kategorie": "wörtlich", "text": "\"Kaffeeobers mit einem Spritzer Kaffee\""}, {"kategorie": "scherzhaft für", "text": "\"Milchkaffee\" (ganz wenig Kaffee mit sehr viel Milch bzw. [[Obers]])"}]'::jsonb, 'Wos mei Oide ''Kaffee'' nennt, is eigentlich nua ''Oowas gschbritzd''!'),
  ('wos-mei-oide-kaffee-nennt-is-eigentlich-nua-oowas-gschbritzd', 'Wos mei Oide ''Kaffee'' nennt, is eigentlich nua ''Oowas gschbritzd''!', '', '', '', 'Wiener Kaffeehaus-ABC', 'Was meine Alte ''Kaffee'' nennt, ist eigentlich nur ''Obers gespritzt''!', '[{"kategorie": "wörtlich", "text": "\"Was meine Alte ''Kaffee'' nennt, ist klassich ''Obers gespritzt'' - fast nur Schlagrahm mit einem Spritzer Kaffee!\"  2. \"Was meine bessere Hälfte für einen ''Kaffee'' hält, ist in Wahrheit ''Obers gespritzt'' - fast nur Schlagrahm mit einem Spritzer Kaffee!\"  3. Sie nennt’s Kaffee – ich nenn’s Obers mit einem Spritzer Espresso!"}]'::jsonb, ''),
  ('zum-kaffee-loss-i-ma-imma-a-klaans-kandal-kaffeeoowas-seawiian', 'Zum Kaffee loss I ma imma a klaans Kandal Kaffeeoowas seawiian!', '', '', '', 'Wiener Kaffeehaus-ABC', 'Zum Kaffee lass ich mir immer ein kleines Kännchen mit frischem Kaffeeobers servieren!', '[{"kategorie": "wörtlich", "text": "\"Zum Kaffee bestelle ich mir immer ein kleines Kännchen Kaffeesahne dazu!\"  2. Ich trinke meinen Kaffee am liebsten mit einem Schuss frischen Kaffeeobers aus dem Kännchen!  3. Ich genieße meinen Kaffee immer mit frischem Kaffeeobers – am besten aus einem separaten Kännchen!"}]'::jsonb, ''),
  ('kaffeeraam-mochd-in-kaffee-mueueda-und-runda-im-gschmock', 'Kaffeeraam mochd in Kaffee müüda und runda im Gschmock!', '', '', '', 'Wiener Kaffeehaus-ABC', 'Kaffeerahm macht den Kaffee milder und runder im Geschmack!', '[{"kategorie": "wörtlich", "text": "\"Mit Kaffeesahne wird der Geschmack des Kaffees weicher und ausgewogener!\"  2. Kaffeerahm verfeinert den Kaffee und nimmt ihm die Bitterkeit!  3. Ein Schuss Kaffeerahm verleiht dem Kaffee eine samtige Geschmeidigkeit!"}]'::jsonb, ''),
  ('zum-noochtisch-beschdoeoe-i-ma-an-farisaea-mit-vueue-rum-und-an-uandlichn-schloogoowashaubal', 'Zum Noochtisch beschdöö I ma an Farisäa mit vüü Rum und an uandlichn Schloogoowashaubal!', '', '', '', 'Wiener Kaffeehaus-ABC', 'Zum Nachtisch bestelle ich mir einen Pharisäer mit viel Rum und einem ordentlichen Schlagobershäubchen!', '[{"kategorie": "wörtlich", "text": "\"Zum Dessert bestelle ich mir einen Pharisäer mit viel Rum und einer ordentlichen Haube Schlagobers!\"  2. Zum Abschluss gönne ich mir einen Pharisäer – mit kräftigem Rum und reichlich Schlagobers obendrauf!  3. Als süßen Ausklang nehme ich einen Pharisäer mit viel Rum und einer großzügigen Haube Schlagsahne!"}]'::jsonb, ''),
  ('si-brausn', 'si brausn', '', '', '', 'Grundwortschatz Wienerisch', 'sich brausen', '[{"kategorie": "wörtlich", "text": "\"sich duschen\" (aus der Fußballersprache übernommen: \"in die Kabine duschen gehen\" - vom mittelhochdeutschen \"brūsen\"=\"brausen\")"}, {"kategorie": "fig.", "text": "einen Abgang machen, weggehen, verschwinden"}]'::jsonb, 'Gee di brausn!'),
  ('gee-di-brausn', 'Gee di brausn!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Geh dich brausen!', '[{"kategorie": "wörtlich", "text": "\"Geh dich duschen!\" (ursprünglich aus der Fußballersprache übernommen: \"in die Kabine duschen gehen\")"}, {"kategorie": "derbe Aufforderung", "text": "Verschwinde!  3. Hau ab!  4. [[Mach]] einen Abgang!  5. [[Zieh]] Leine!  6.[[Gee]] päule!  7. [[Moch]] a Woikn!"}]'::jsonb, 'si brausn'),
  ('si-brausn-gee-kennan', 'si brausn gee kennan', '', '', '', 'Wiener Sprüche, die sitzen!', 'sich brausen gehen können', '[{"kategorie": "wörtlich", "text": "\"sich etwas abschminken können\""}, {"kategorie": "", "text": "sich etwas aus dem Kopf schlagen können"}, {"kategorie": "", "text": "sich etwas in die Haare schmieren können"}]'::jsonb, 'Mit da Gehoidsseahöhung, des wiad nix - do kaunn I mi brausn gee!'),
  ('mit-da-gehoidsseahoehung-des-wiad-nix-do-kaunn-i-mi-brausn-gee', 'Mit da Gehoidsseahöhung, des wiad nix - do kaunn I mi brausn gee!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Mit der Gehaltserhöhung, das wird nix - da kann ich mich brausen gehen!', '[{"kategorie": "wörtlich", "text": "\"Mit der Gehaltserhöhung, das wird nichts - die kann ich mir abschminken!\"  2. Mit der Gehaltserhöhung, das wird nichts - die kann ich mir getrost in die Haare schmieren!  3. Auf die Gehaltserhöhung kann ich wohl lange warten – die kann ich mir gepflegt sonstwohin stecken!"}]'::jsonb, ''),
  ('mein-obstla-brenn-i-ma-soeoewa', 'Mein Obstla brenn I ma sööwa!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Meinen Obstler brenn ich mir selber!', '[{"kategorie": "wörtlich", "text": "\"Meinen Obstbrand brenn ich mir selbst!\"  2. Den Obstler mach ich selbst – vom Baum bis ins Glas!  3. A g’scheiter Schnaps kommt aus’m eigenen Kessel!"}]'::jsonb, ''),
  ('mia-brennan-de-gucka-vom-rauch', 'Mia brennan de Gucka vom Rauch!', '', '', '', 'Krank & kuriert auf Wienerisch', 'Mir brennen die Gucker vom Rauch!', '[{"kategorie": "wörtlich", "text": "\"Mir brennen die Augen vom Rauch!\"  2. Meine Augen brennen vom Rauch!  3. Der Rauch frisst sich wie Nadeln in meine Augen!"}]'::jsonb, ''),
  ('de-hittn-hod-lichtaloo-brennd', 'De Hittn hod lichtaloo brennd!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Die Hütte hat lichterloh gebrannt!', '[{"kategorie": "wörtlich", "text": "\"Das Lokal stand komplett in Flammen!\"  2. Die Flammen haben das ganze Haus erfasst!  3. Ein einziges Flammenmeer hat die Hütte binnen weniger Minuten komplett verschlungen!"}]'::jsonb, ''),
  ('wea-brennd-de-letzte-rechnung', 'Wea brennd de letzte Rechnung?', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Wer brennt die letzte Rechnung?', '[{"kategorie": "wörtlich", "text": "\"Wer bezahlt die letzte Rechnung?\"  2. Wer übernimmt die letzte Rechnung?  3. Wer zahlt die letzte Runde?"}]'::jsonb, ''),
  ('im-frueuejoa-treibm-de-wiidln-in-zoatem-gruen-aus', 'Im Früüjoa treibm de Wiidln in zoatem Grün aus!', '', '', '', 'Botanik und Pflanzen auf Wienerisch', 'Im Frühjahr treiben die Wideln in zartem Grün aus!', '[{"kategorie": "wörtlich", "text": "\"Im Frühjahr treiben die Weidenzweige in zartem Grün aus!\"  2. Die Weide bildet im Frühjahr neue Triebe mit zartgrünen Blättern!  3. Im Frühling beginnt das feine Grün der jungen Weidentriebe zu sprießen!"}]'::jsonb, ''),
  ('de-wiidln-miassn-brennd-sei', 'De Wiidln miassn brennd sei!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Die Wideln müssen gebrannt sein!', '[{"kategorie": "wörtlich", "text": "\"Die Haare müssen mit einem Brenneisen gestylt sein!\"  2. Die Haare müssen mit einem Glätteisen in Form gebracht sein!  3. Die Haare müssen mit einem Lockeneisen dauergewellt sein!"}]'::jsonb, ''),
  ('i-pock-di-glei-bei-de-wiidln', 'I pock di glei bei de Wiidln!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Ich pack dich gleich bei den Wideln!', '[{"kategorie": "wörtlich", "text": "\"Ich pack dich gleich am Schopf!\"  2. Ich greif dir gleich in die Mähne!  3. Ich hab dich gleich am Schlawittchen!"}]'::jsonb, ''),
  ('brennan-wiara-lusta', 'brennan wiara Lusta', '', '', '', 'Wiener Sprüche, die sitzen!', 'brennen wie ein Luster', '[{"kategorie": "wörtlich", "text": "\"wie ein Kronleuchter brennen\""}, {"kategorie": "scherzhaft für", "text": "\"blechen wie ein Bankomat\", aus der Geldbörse bluten, alles berappen wie ein Goldesel"}, {"kategorie": "", "text": "unverhältnismäßig viel bezahlen müssen, sehr tief in die Tasche greifen müssen, kräftig blechen müssen"}]'::jsonb, 'Fiad Hochzeit hob I brennd wiara Lusta!'),
  ('sei-oida-brennd-wiara-lusta', 'Sei Oida brennd wiara Lusta!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Sein Alter brennt wie ein Luster', '[{"kategorie": "wörtlich", "text": "\"Sein Vater brennt wie ein Luster!\"   2. (scherzhaft für): Sein Vater blecht wie ein Bankomat!  3. Sein Vater blutet aus der Geldbörse!  4. Sein Vater zahlt und zahlt - wie ein Goldesel!"}]'::jsonb, 'brennan wiara Lusta'),
  ('fiad-hochzeit-hob-i-brennd-wiara-lusta', 'Fiad Hochzeit hob I brennd wiara Lusta!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Für die Hochzeit hab ich gebrannt wie ein Luster!', '[{"kategorie": "wörtlich", "text": "\"Für die Hochzeit hab ich ordentlich was hinlegen müssen!\"  2. Für die Hochzeit hab ich sehr tief in die Tasche greifen müssen!  3. Die Hochzeit hat mich ein kleines Vermögen gekostet!"}]'::jsonb, 'brennan wiara Lusta'),
  ('wem-ane-aufbrenna', 'wem ane aufbrenna', '', '', '', 'Wiener Sprüche, die sitzen!', 'jemandem eine aufbrennen', '[{"kategorie": "wörtlich", "text": "\"jemandem eine brennende Ohrfeige auflegen\" (vom mittelhochdeutschen \"ūfbrennen\"=\"aufbrennen\")"}, {"kategorie": "allg.", "text": "\"jemandem glühende Schmerzen verursachen\", \"jemandem eine schallende, brennende Ohrfeige verpassen\", jemandem eine scheuern, [[auflegen]], [[schmieren]]"}]'::jsonb, 'Waunna no amoi de Goschn aufreissd, brenn I eam ane auf!'),
  ('waunna-no-amoi-de-goschn-aufreissd-brenn-i-eam-ane-auf', 'Waunna no amoi de Goschn aufreissd, brenn I eam ane auf!', '', '', '', 'Wiener Gaunersprache', 'Wenn er noch einmal die Goschen aufreißt, brenn ich ihm eine auf!', '[{"kategorie": "wörtlich", "text": "\"Wenn er noch einmal das Maul aufreißt, verpass ich ihm eine schallende, brennende Ohrfeige!\"  2. Reißt der noch einmal so frech die [[Pappen]] auf, knallt’s ordentlich!  3. Noch ein frecher Mucks, und er hat meine fünf Finger im Gesicht brennen!"}]'::jsonb, 'wem ane aufbrenna'),
  ('ia-oida-geed-fremdpuudan', 'Ia Oida geed fremdpuudan!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Ihr Alter geht fremdpudern!', '[{"kategorie": "wörtlich", "text": "\"Ihr Ehemann vögelt auswärts!\"  2. (scherzhaft für): \"Ihr Göttergatte geht auswärts [[pudern]]!  3. Ihr Angetrauter turnt in fremden Betten!"}]'::jsonb, ''),
  ('gib-ma-a-glasl-vom-oidn-da-heiriche-is-ma-zu-saua', 'Gib ma a Glasl vom Oidn - da Heiriche is ma zu saua!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Gib mir ein Gläschen vom Alten - der Heurige ist mir zu sauer!', '[{"kategorie": "wörtlich", "text": "\"Gib mir ein Gläschen vom Altwein - der Jungwein ist mir zu sauer!\"  2. Ich nehme lieber ein Glas Altwein – der Heurige ist mir zu spritzig!  3. Ich bevorzuge einen reiferen Tropfen – der Heurige liegt mir nicht so!"}]'::jsonb, ''),
  ('da-oide-hockd-aum-schdaummtisch-wia-seit-dreissig-joa-und-waass-wia-imma-ollas-bessa', 'Da Oide hockd aum Schdaummtisch wia seit dreissig Joa - und waass wia imma ollas bessa!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Der Alte hockt am Stammtisch wie seit dreißig Jahren – und weiß wie immer alles besser!', '[{"kategorie": "wörtlich", "text": "\"Der alte Mann hockt am Stammtisch wie seit dreißig Jahren – und weiß wie immer alles besser!\"  2. Seit Jahrzehnten sitzt der alte Herr am Stammtisch und weiß - wie immer - alles besser!  3. Der Opa pickt wie festgewachsen am Stammtisch und weiß wie immer alles - besser, lauter, länger!"}]'::jsonb, ''),
  ('oida-auf-uns', 'Oida, auf uns!', '', '', '', 'Wiener Jugendsprache & Teenie-Talk', 'Alter, auf uns!', '[{"kategorie": "wörtlich", "text": "\"Auf uns, Kumpel!\"  2. Prost, mein Freund!  3. Bruder, auf uns!  4. Cheers, mein Bester!"}]'::jsonb, ''),
  ('oida-sei-ned-so', 'Oida, sei ned so!', '', '', '', 'Wiener Jugendsprache & Teenie-Talk', 'Alter, sei nicht so!', '[{"kategorie": "wörtlich", "text": "\"Mann, sei nicht so!\"  2. Junge, stell dich nicht so an!  3. Bruder, jetzt mach mal halblang!"}]'::jsonb, ''),
  ('de-oide-kommandiad-uns-in-da-fiama-umanaund-ois-warad-ma-olle-iare-klaanan-buam', 'De Oide kommandiad uns in da Fiama umanaund, ois warad ma olle iare klaanan Buam!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Die Alte kommandiert uns in der Firma herum, als wären wir alle ihre kleinen Buben!', '[{"kategorie": "wörtlich", "text": "\"Die Chefin kommandiert uns in der Firma rum, als wären wir alle ihre kleinen Buben!\"  2. Die Chefin kommandiert uns in der Firma rum, als wär sie unsere Kindergartentante!  3. Die Chefin hupft bei uns in der Firma rum, wie wenn sie lauter Lausbuben dirigieren tät!"}]'::jsonb, ''),
  ('da-bua-grood-komplett-noch-da-oidn', 'Da Bua grood komplett noch da Oidn!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Der Bub gerät komplett nach der Alten!', '[{"kategorie": "wörtlich", "text": "\"Der Bub gerät komplett nach seiner Mutter!\"  2. Der Junge kommt ganz nach seiner Mutter!  3. Der Bub ähnelt seiner Mutter nicht nur äußerlich, sondern auch im Charakter!"}]'::jsonb, ''),
  ('host-scho-sei-neiche-oide-gseeng-a-supa-resche-schnittn', 'Host scho sei neiche Oide gseeng - a supa resche Schnittn!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Hast du schon seine neue Alte gesehen - eine super resche Schnitte!', '[{"kategorie": "wörtlich", "text": "\"Hast du schon seine neue Freundin gesehen - eine super resche Schnitte!\"  2. Hast du schon seine Neue gesehen? Richtig fesche Maus, sag ich dir!  3. Hast du seine neue Braut gesehen - schaut echt knackig aus!"}]'::jsonb, ''),
  ('de-oide-is-zum-vagessn', 'De Oide is zum Vagessn!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Die Alte ist zum Vergessen!', '[{"kategorie": "wörtlich", "text": "\"Dieses Weib ist zum Vergessen!\"  2. Diese Frau ist eine echte Nullnummer!  3. An dieses Frauenzimmer verschwendet man am besten keinen Gedanken!  4. Diese Frau kannst du gleich streichen!"}]'::jsonb, ''),
  ('da-oide-zoid-ma-kaane-iwaschdundn', 'Da Oide zoid ma kaane Iwaschdundn!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Der Alte zahlt mir keine Überstunden!', '[{"kategorie": "wörtlich", "text": "\"Mein Boss rückt kein Geld für Überstunden raus!\"  2. Mein Chef zahlt mir keinen Cent für die Überstunden!  3. Für Überstunden krieg ich vom Alten rein gar nichts!"}]'::jsonb, ''),
  ('oida-des-gibts-jo-ned', 'Oida, des gibts jo ned!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Alter, das gibt''s ja nicht!', '[{"kategorie": "wörtlich", "text": "\"Mann, das gibt''s doch nicht!\"  2. Verdammt Mann, das kann doch nicht wahr sein!  3. Herrgott nochmal, das ist ja nicht zu fassen!"}]'::jsonb, ''),
  ('supa-gmochd-oida', 'Supa gmochd, Oida!', '', '', '', 'Wiener Jugendsprache & Teenie-Talk', 'Super gemacht, Alter!', '[{"kategorie": "wörtlich", "text": "\"Mann, Respekt!\"  2. Bravo, Mann!  3. Alle Achtung, Junge!  4. Mensch, toll gemacht!"}]'::jsonb, ''),
  ('oida-uageil', 'Oida, uageil!', '', '', '', 'Wiener Jugendsprache & Teenie-Talk', 'Alter, ur geil!', '[{"kategorie": "wörtlich, Jugendsprache", "text": "\"Alter, das ist der Hammer!\"  2. Junge, das ist mega!  3. Bruder, das ist affengeil!  4. Mann, das ist voll abgefahren!"}]'::jsonb, ''),
  ('oida-wos-soi-des', 'Oida, wos soi des?', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Alter, was soll das?', '[{"kategorie": "wörtlich", "text": "\"Mann, was soll das?\"  2. Mann, das geht gar nicht!  3. Mensch, bist du völlig daneben?"}]'::jsonb, ''),
  ('wos-wueuesd-oida', 'Wos wüüsd, Oida?', '', '', '', 'Wiener Jugendsprache & Teenie-Talk', 'Was willst du, Alter?', '[{"kategorie": "wörtlich", "text": "\"Mann, was willst du?\"  2. Mann, pass nur ja auf!  3. Mensch, was gibt''s denn?"}]'::jsonb, ''),
  ('oida-wos-braucht-dea-trottl-do-vuan-so-laung', 'Oida, wos braucht dea Trottl do vuan so laung?', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Alter, wieso braucht der Trottel da vorne so lang?', '[{"kategorie": "wörtlich, als Diskursmarker", "text": "\"Verdammt Mann, wieso braucht der Trottel da vorne so lange?\"  2. Verflixt Mann, warum ist der Typ da vorne so langsam?  3. Mensch, wieso trödelt der Idiot da vorne so lange herum?"}]'::jsonb, ''),
  ('heast-oida-wia-geeds-da', 'Heast Oida, wia geeds da?', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Hör mal, Alter, wie geht''s dir?', '[{"kategorie": "wörtlich, als Diskursmarker", "text": "\"Verdammt Mann, geht''s dir noch gut?\"  2. Verdammt, Alter, bist du noch bei Sinnen?  3. Mensch, du Idiot, hast du sie noch alle?"}]'::jsonb, ''),
  ('i-trink-zu-jedn-kriagl-ois-vaschdaeaka-an-brueljantn', 'I trink zu jedn Kriagl ois Vaschdäaka an Brüljantn!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Ich trink zu jedem Krügel als Verstärker einen Brillanten!', '[{"kategorie": "wörtlich", "text": "\"Ich trink zu jeder Halben als Verstärker einen Klaren!\"  2. Mit jedem Bier ein Klarer – so bleibt die Balance im Blut!  3. Ein kühles Bier, ein klarer Geist – das gehört für mich zusammen wie das Amen im Gebet!"}]'::jsonb, ''),
  ('da-brueljant-is-peafekt-gschliffn-a-echta-bruella', 'Da Brüljant is peafekt gschliffn - a echta Brülla!', '', '', '', 'Wiener Gaunersprache', 'Dieser Brillant ist perfekt geschliffen – ein echt toller Brüller!', '[{"kategorie": "wörtlich", "text": "\"Dieser Brillant ist perfekt geschliffen – ein echt toller Diamantring!\"  2. Dieser Diamant besticht durch seinen perfekten Schliff – ein wahres Schmuckstück, dieser Brillantring!  3. Dieser Brillant ist makellos geschliffen – ein wirklich besonders edler Diamantring!"}]'::jsonb, ''),
  ('es-is-zwoa-unsa-wiign-aum-brueljantngrund-glaant-owa-unsa-vooda-woa-ka-haushea-und-ka-seidnfabrikant', 'Es is zwoa unsa Wiign aum Brüljantngrund glaant - owa unsa Vooda woa ka Haushea und ka Seidnfabrikant!', '', '', '', 'Wiener Wörter mit schillernder Geschichte', 'Es ist zwar unsere Wiege am Brillantengrund gelehnt - aber unser Vater war kein Hausherr und kein Seidenfabrikant!', '[{"kategorie": "wörtlich, Textzeile eines Altwienerlieds", "text": "\"Unsere Wiege stand wohl am Brillantengrund, doch unser Vater war weder Grundbesitzer noch Seidenbaron!\"  2. Wir kamen am noblen Wiener Brillantengrund zur Welt, doch unser Vater war weder Hausherr noch ein Mann von Stand!  3. Ja, wir sind am Brillantengrund aufgewachsen – aber unser Vater war weder Hausherr noch ein reicher Seidenfabrikant!"}]'::jsonb, ''),
  ('ea-is-a-biiz-vom-diamantngrund-owa-gscheid-hackld-hoda-no-nii', 'Ea is a Biiz vom Diamantngrund - owa gscheid hackld hoda no nii!', '', '', '', 'Wiener Wörter mit schillernder Geschichte', 'Er ist ein Biz vom Diamantengrund - aber g''scheit gehackelt hat er noch nie!', '[{"kategorie": "wörtlich", "text": "\"Er ist ein reicher Dandy aus der Wiener Vorstadt - aber richtig gearbeitet hat er noch nie!\"  2. Er ist ein wohlhabender Schöngeist aus der Wiener Vorstadt – aber schuften musste er nie!  3. Er ist ein typisches Wohlstandssöhnchen aus der Wiener Vorstadt – schön leben, nichts tun!"}]'::jsonb, ''),
  ('brisiil', 'Brisììl', 'die', '', '', 'Wiener Wörter mit schillernder Geschichte', 'Brisouille', '[{"kategorie": "wörtlich", "text": "\"Brisouille\" (vom mittelhochdeutschen \"brissul\"=\"Schandpfahl\", altfranzösisch \"brisouille\")"}, {"kategorie": "fig.", "text": "Zwangslage, Zwickmühle, Patsche, Klemme, [[Bredouille]]"}]'::jsonb, 'Olle sans oghaud, und mi haums in da Brisììl sitzn lossn!'),
  ('in-da-brisuul-sitzn', 'in da Brisuul sitzn', '', '', '', 'Wiener Sprüche, die sitzen!', 'in der Brisouille sitzen', '[{"kategorie": "wörtlich", "text": "\"in der Klemme sitzen\""}, {"kategorie": "", "text": "in der Patsche stecken"}, {"kategorie": "", "text": "in der [[Bredouille]] sein"}]'::jsonb, ''),
  ('in-da-brisiil-sitzn', 'in da Brisììl sitzn', '', '', '', 'Wiener Sprüche, die sitzen!', 'in der Brisouille sitzen', '[{"kategorie": "wörtlich", "text": "\"in der Klemme sitzen\""}, {"kategorie": "", "text": "in der Patsche stecken"}, {"kategorie": "", "text": "in der [[Bredouille]] sein"}]'::jsonb, ''),
  ('olle-sans-oghaud-und-mi-haums-in-da-brisuul-sitzn-lossn', 'Olle sans oghaud, und mi haums in da Brisuul sitzn lossn!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Alle sind sie abgehauen, und mich haben sie in der Brisouille sitzen lassen!', '[{"kategorie": "wörtlich", "text": "\"Alle sind sie abgehauen, und mich haben sie in der Klemme sitzen lassen!\"  2. Alle haben sich aus dem Staub gemacht, und ich bin auf dem Schlamassel sitzen geblieben!  3. Alle haben Reißaus genommen und mich haben sie in der Brisouille sitzen lassen!"}]'::jsonb, 'in da Brisuul sitzn'),
  ('olle-sans-oghaud-und-mi-haums-in-da-brisiil-sitzn-lossn', 'Olle sans oghaud, und mi haums in da Brisììl sitzn lossn!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Alle sind sie abgehauen, und mich haben sie in der Brisouille sitzen lassen!', '[{"kategorie": "wörtlich", "text": "\"Alle sind sie abgehauen, und mich haben sie in der Klemme sitzen lassen!\"  2. Alle haben sich aus dem Staub gemacht, und ich bin auf dem Schlamassel sitzen geblieben!  3. Alle haben Reißaus genommen und mich haben sie in der Brisouille sitzen lassen!"}]'::jsonb, 'in da Brisììl sitzn'),
  ('mei-freind-hod-no-an-oidn-breezlkaeaefa-und-dea-foad-sogoa-no', 'Mei Freind hod no an oidn Breezlkääfa - und dea foad sogoa no!', '', '', '', 'Wiener Mechaniker-Slang', 'Mein Freund hat noch einen alten Brezelkäfer - und der fährt sogar noch!', '[{"kategorie": "wörtlich", "text": "\"Mein Freund hat noch einen alten VW-Käfer mit diesem ovalen, brezelförmigen Heckfenster - und die Karre fährt sogar noch!\"  2. Mein [[Haberer]] besitzt noch einen alten VW Käfer mit dem typischen Brezelfenster – und der läuft immer noch!  3. Mein Freund hat noch so eine alte Käfer-Karre mit dem legendären Brezelfenster – und das Ding rollt tatsächlich noch!"}]'::jsonb, ''),
  ('dea-hod-in-da-noadwaund-a-breezn-grissn-a-echte-todesbreezn-direkt-owe-oone-an-ton', 'Dea hod in da Noadwaund a Breezn grissn - a echte Todesbreezn, direkt owe, oone an Ton!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Der hat in der Nordwand eine Brezen gerissen - eine echte Todesbrezen, direkt hinab, ohne einen Ton!', '[{"kategorie": "wörtlich", "text": "\"Der ist in der Nordwand abgestürzt - tödlich verunglückt, direkt runter, ohne einen Ton!\"  2. Er ist bei einem Absturz in der Bergwand tödlich verunglückt – lautlos, ohne jede Chance!  3. Er ist in der Nordwand tödlich abgestürzt – ein Sturz in die Tiefe, ohne einen Laut!"}]'::jsonb, ''),
  ('bevua-i-a-todesbreezn-reiss-kauf-i-ma-liawa-doch-ka-neichs-eisn', 'Bevua I a Todesbreezn reiss, kauf I ma liawa doch ka neichs Eisn!', '', '', '', 'Wiener Mechaniker-Slang', 'Bevor ich eine Todesbrezen reiße, kauf ich mir lieber doch kein neues Eisen!', '[{"kategorie": "wörtlich", "text": "\"Bevor ich einen tödlichen Sturz hinlege, kauf ich mir lieber doch kein neues Motorrad!\"  2. Bevor ich mich mit ’nem heißen Eisen in die Ewigkeit schieß, lass ich das Motorradfahren lieber gleich!  3. Ein Motorrad ist mir einfach zu gefährlich – ich verzichte lieber auf ein neues!"}]'::jsonb, ''),
  ('zum-fruaschduck-iss-i-aum-liabstn-a-frische-breezn-mit-butta', 'Zum Fruaschduck iss I aum liabstn a frische Breezn mit Butta!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Zum Frühstück esse ich am liebsten eine frische Brezen mit Butter!', '[{"kategorie": "wörtlich", "text": "\"Zum Frühstück esse ich am liebsten eine frische Brezel mit Butter!\"  2. Morgens geht für mich nichts über eine ofenwarme Brezel mit Butter!  3. Eine Brezen mit Butter ist mein Standardfrühstück!"}]'::jsonb, ''),
  ('a-breezn-und-a-bia-mea-brauchds-ned-zum-glick', 'A Breezn und a Bia - mea brauchds ned zum Glick!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Eine Brezen und ein Bier - mehr braucht''s nicht zum Glück!', '[{"kategorie": "wörtlich", "text": "\"Eine Brezel und ein Bier - mehr braucht''s nicht zum Glück!\"  2. Bier und Brezen - mehr brauch ich nicht zum Glücklichsein!  3. Ein frisches Bier, eine resche Brezn – was will man mehr?"}]'::jsonb, ''),
  ('a-breezl-und-a-bia-mea-brauchds-ned-zum-glick', 'A Breezl und a Bia - mea brauchds ned zum Glick!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Ein Brezel und ein Bier - mehr braucht''s nicht zum Glück!', '[{"kategorie": "wörtlich", "text": "\"Brezel und Bier - mehr braucht''s nicht zum Glück!\"  2. Bier und Brezel - mehr brauch ich nicht zum Glücklichsein!  3. Ein frisches Bier, ein resches Brezel – was will man mehr?"}]'::jsonb, ''),
  ('a-breezn-reissn', 'a Breezn reissn', '', '', '', 'Wiener Sprüche, die sitzen!', 'eine Brezen reißen', '[{"kategorie": "wörtlich", "text": "\"einen Sturz reißen und dann daliegen wie eine [[Brezen]]\" (vom mittelhochdeutschen \"preze\"=\"Gebäck in Form verschlungener Arme\")"}, {"kategorie": "allg.", "text": "stürzen, hinfallen, [[einen]] Stern reißen, [[ein]] Kipferl reißen"}, {"kategorie": "fig.", "text": "Schiffbruch erleiden, eine Niederlage einstecken müssen, eine Schlappe erleiden"}, {"kategorie": "scherzhaft für", "text": "sterben, [[maukas]] gehen, [[ein]] Bankerl reißen"}]'::jsonb, ''),
  ('de-neiche-app-is-technisch-a-anzige-breezn-nonstop-nix-ois-obstueaze', 'De neiche App is technisch a anzige Breezn - nonstop nix ois Obstüaze!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Die neue App ist technisch eine einzige Brezen – nonstop nichts als Abstürze!', '[{"kategorie": "wörtlich", "text": "\"Die neue App ist technisch eine einziges Debakel – Abstürze nonstop!\"  2. Die neue App ist technisch eine totale Katastrophe – ständig crasht das Ding!  3. Die neue App ist - technisch gesehen - ein Totalausfall. Sobald man was tippt, stürzt sie ab!"}]'::jsonb, ''),
  ('des-woara-uandliche-breezn', 'Des woara uandliche Breezn!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Das war eine ordentliche Brezen!', '[{"kategorie": "wörtlich", "text": "Das war ein gehöriger Bauchfleck!  2. Das war ein totaler Reinfall!  3. Das war eine volle Bruchlandung"}]'::jsonb, ''),
  ('hau-da-a-gscheide-lodung-brimsn-aufs-brood-daunn-reed-ma-weida', 'Hau da a gscheide Lodung Brimsn aufs Brood, daunn reed ma weida!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Hau dir eine g''scheite Ladung Primsen aufs Brot, dann reden wir weiter!', '[{"kategorie": "wörtlich", "text": "\"Hau dir eine g''scheite Ladung Schafsfrischkäse aufs Brot, dann reden wir weiter!\"  2. Schmier dir erst mal ordentlich Primsen aufs Brot, dann reden wir weiter!  3. Pack dir eine fette Schicht von dem Schafstopfen aufs Brot, dann reden wir weiter!"}]'::jsonb, ''),
  ('heast-brimsnneega-zaa-da-moi-a-bissl-a-sunn-eine', 'Heast, Brimsnneega, zaa da moi a bissl a Sunn eine!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Hör mal, du Brimsenneger, zieh dir mal ein bisschen Sonne rein!', '[{"kategorie": "wörtlich", "text": "\"Hör mal, du Käsegesicht, zieh dir mal ein bisschen Sonne rein!\"  2. Ey, du wandelnder Mozzarella - geh mal raus ans Tageslicht!  3. Hey, du [[Topfenneger]], geh mal raus an die frische Luft – du siehst aus wie ‘n vergessener Joghurt im Kühlschrank!"}]'::jsonb, ''),
  ('schiab-da-a-brioosch-in-hois-bevuasd-wiida-zum-suudan-aufaungst', 'Schiab da a Brioosch in Hois, bevuasd wiida zum Suudan aufaungst!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Schieb dir eine Brioche in den Hals, bevor du wieder zum Sudern anfängst!', '[{"kategorie": "wörtlich", "text": "\"Schieb dir ein Hefebrötchen in den Hals, bevor du wieder zu motzen anfängst!\"  2. Gönn dir erstmal ''ne Brioche – zicken kannst du später immer noch!  3. Lass dir erstmal die Brioche schmecken und heb dir das Gejammer für später auf!"}]'::jsonb, ''),
  ('im-topf-broodls-nuudlwossa', 'Im Topf broodls Nuudlwossa!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Im Topf brodelt das Nudelwasser!', '[{"kategorie": "wörtlich", "text": "\"Im Topf blubbert das Nudelwasser!\"  2. Das Wasser für die Nudeln kocht schon!  3. Im Topf sprudelt’s - gib jetzt die Nudeln dazu!"}]'::jsonb, ''),
  ('broodl-ned-asoo', 'Broodl ned asoo!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Brodle nicht so sehr!', '[{"kategorie": "wörtlich", "text": "Trödle nicht so lang herum!  2. Lass dir nicht so viel Zeit!  3. Mach ein bisschen schneller!"}]'::jsonb, ''),
  ('dea-broodld-umanaund-wiara-rentna-auf-valium', 'Dea broodld umanaund wiara Rentna auf Valium!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Der brodelt herum wie ein Rentner auf Valium!', '[{"kategorie": "wörtlich", "text": "\"Der trödelt herum wie ein Rentner auf Valium!\"  2. Der bewegt sich, als wäre er auf Zeitlupe eingestellt!  3. Der trödelt herum, als hätte er alle Zeit der Welt!"}]'::jsonb, ''),
  ('kumm-endlich-du-broodla-da-bus-woat-ned-auf-uns', 'Kumm endlich, du Broodla, da Bus woat ned auf uns!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Komm endlich, du Brodler, der Zug wartet nicht auf uns!', '[{"kategorie": "wörtlich", "text": "\"Komm endlich, du Trödler, der Zug wartet nicht auf uns!\"  2. Beweg dich endlich, du Langsamtreter, sonst fährt uns der Bus noch vor der Nase weg!  3. Komm schon, du Bummler, beeil dich ein bisschen – der Bus wartet nicht!"}]'::jsonb, ''),
  ('breesl-reibm', 'Breesl reibm', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Brösel reiben', '[{"kategorie": "wörtlich", "text": "\"aus harten Semmeln Krumen reiben\" (vom mittelhochdeutschen \"brōsamlīn\"=\"Brösämlein\")"}, {"kategorie": "scherzhaft für", "text": "x-beinig gehen, mit nach innen gedrehten Beinen laufen, [[stricken]] (\"leicht kniegeneigt gehen\")"}]'::jsonb, 'Des is zum Breeslreibm!'),
  ('de-oma-hod-nii-paniamoeoe-kaufd-sii-hod-de-breesl-imma-soeoewa-griibm', 'De Oma hod nii Paniamöö kaufd - sii hod de Breesl imma sööwa griibm!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Die Oma hat nie Paniermehl gekauft - sie hat die Brösel immer selber gerieben!', '[{"kategorie": "wörtlich", "text": "\"Die Oma hat nie Paniermehl gekauft - sie hat die Krumen immer selbst gerieben!\"  2. Oma hat ihre Brösel immer selbst gerieben – gekauftes Paniermehl kam ihr nicht ins Haus!  3. Statt fertiges Paniermehl zu nehmen, hat Oma die Brösel immer selbst gerieben!"}]'::jsonb, ''),
  ('dea-geed-ois-taeda-zwischnd-fiass-breesl-reibm-gaunz-wia-da-opa-noochn-schnops', 'Dea geed, ois täda zwischnd Fiass Breesl reibm - gaunz wia da Opa noochn Schnops!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Der geht, als täte er zwischen den Beinen Brösel reiben – ganz wie der Opa nach’m Schnaps!', '[{"kategorie": "wörtlich", "text": "\"Der geht, als würde er zwischen den Beinen Krumen reiben – ganz wie der Opa nach''m Schnaps!\"  2. Der reibt Brösel beim Gehen, ganz wie der Opa nach''m Schnaps!  3. Der schleicht dahin, als würd er beim Gehen mit jedem Schritt still und heimlich Brösel reiben - ganz wie der Opa nach''m Schnaps!"}]'::jsonb, 'Breesl reibm'),
  ('des-is-zum-breeslreibm', 'Des is zum Breeslreibm!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Das ist zum Bröselreiben!', '[{"kategorie": "wörtlich", "text": "\"Das ist für nichts und wieder nichts!\"  2. Das ist für die [[Katz]]!  3. Das ist reine Zeitverschwendung!"}]'::jsonb, ''),
  ('glei-gibds-breesln', 'Glei gibds Breesln!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Gleich gibt es Brösel!', '[{"kategorie": "wörtlich", "text": "\"Gleich gibt es Ärger!\"  2. Gleich kracht''s!  3. Gleich fliegen die Fetzen!  4. Gleich wird''s haarig!  5. Gleich geht''s zur Sache!"}]'::jsonb, ''),
  ('fia-den-breeslgeia-wueuesd-aa-noo-goeoed', 'Fia den Breeslgeia wüüsd aa noo Gööd?', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Für diesen Bröselgeier willst du auch noch Geld?', '[{"kategorie": "scherzhaft für", "text": "Für diese frittierten Krümelgeier willst du auch noch Geld?  2. Für diesen frittierten Bröselvogel  soll ich bezahlen?  3. Für diesen Paniermantel mit ein bisschen Huhn willst du Geld?"}]'::jsonb, ''),
  ('fia-den-breeslfleck-wueuesd-aa-noo-goeoed', 'Fia den Breeslfleck wüüsd aa noo Gööd?', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Für diesen Bröselfleck willst du auch noch Geld?', '[{"kategorie": "scherzhaft für", "text": "Für diese Panadenmatte willst du auch noch Geld?  2. Für diesen frittierten Bröselteppich  soll ich bezahlen?  3. Für diesen Paniermantel mit ein bisschen Fleisch willst du Geld?"}]'::jsonb, ''),
  ('fia-den-breesldaeaewich-wueuesd-aa-noo-goeoed', 'Fia den Breesldääwich wüüsd aa noo Gööd?', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Für diesen Bröselteppich willst du auch noch Geld?', '[{"kategorie": "scherzhaft für", "text": "Für diese Panadenmatte willst du auch noch Geld?  2. Für diesen frittierten Bröselfleck  soll ich bezahlen?  3. Für diesen Paniermantel mit ein bisschen Fleisch willst du Geld?"}]'::jsonb, ''),
  ('fia-den-breeslfetzn-wueuesd-aa-noo-goeoed', 'Fia den Breeslfetzn wüüsd aa noo Gööd?', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Für diesen Bröselfetzen willst du auch noch Geld?', '[{"kategorie": "scherzhaft für", "text": "Für diese Panadenmatte willst du auch noch Geld?  2. Für diesen frittierten Bröselteppich  soll ich bezahlen?  3. Für diesen Paniermantel mit ein bisschen Fleisch willst du Geld?"}]'::jsonb, ''),
  ('unsa-breeslmaschin-is-no-von-da-uarli-massivs-metoi-afoch-unvawueuesdlich', 'Unsa Breeslmaschin is no von da Uarli - massivs Metoi, afoch unvawüüsdlich!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Unsere Bröselmaschine ist noch von der Uroma – massives Metall, einfach unverwüstlich!', '[{"kategorie": "wörtlich", "text": "\"Unsere Bröselreibe stammt noch von der Uroma – ein massives Metallgerät, aber unverwüstlich!\"  2. Die Bröselreibe ist ein Erbstück von der Uroma – aus schwerem Metall, funktioniert aber immer noch einwandfrei!  3. Die Bröselmaschine von der Uroma ist aus Gusseisen – unkaputtbar, obwohl steinalt!"}]'::jsonb, ''),
  ('mit-dea-breeslmaschin-kaunnst-ned-auf-ualaub-foan', 'Mit dea Breeslmaschin kaunnst ned auf Ualaub foan!', '', '', '', 'Wiener Mechaniker-Slang', 'Mit dieser Bröselmaschine kannst du nicht auf Uraub fahren!', '[{"kategorie": "wörtlich", "text": "\"Mit dieser Klapperkiste kannst du nicht auf Urlaub fahren, die zerbröselt dir!\"  2. Mit dieser altersschwachen Karre kannst du nicht auf Urlaub fahren, die fällt dir auseinander!  3. Diese Schrottkarre hält doch keine 100 Kilometer durch – die zerbröselt dir wie ein Keks!"}]'::jsonb, ''),
  ('moch-kane-breesln', 'Moch kane Breesln!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Mach keine Brösel!', '[{"kategorie": "wörtlich", "text": "\"Mach keine Probleme!\"  2. Mach keinen Ärger!  3. Provoziere keinen Streit!"}]'::jsonb, ''),
  ('do-gibts-breesln', 'Do gibt’s Breesln!', '', '', '', 'Wiener Gaunersprache', 'Da gibt es Brösel!', '[{"kategorie": "wörtlich", "text": "\"Da gibt es Probleme\""}, {"kategorie": "", "text": "Da gibt es Ärger!  3. Da gibt''s Querelen!"}]'::jsonb, ''),
  ('kind-iss-bitte-iwan-toella-du-breeslsd-scho-wiida-ollas-voi', 'Kind, iss bitte iwan Tölla - du breeslsd scho wiida ollas voi!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Kind, iss bitte über dem Teller – du bröselst schon wieder alles voll!', '[{"kategorie": "wörtlich", "text": "\"Kind, iss bitte über dem Teller – du krümelst schon wieder alles voll!\"  2. Schatz, iss bitte über dem Teller - es bröselt sonst wieder überall hin!  3. Kind, dein Essen gehört auf den Teller - brösel nicht alles auf den Boden!"}]'::jsonb, ''),
  ('do-breeslds-im-lautschbrecha-ois-haed-si-a-sock-naeaegl-drin-vaiad', 'Do breeslds im Lautschbrecha, ois häd si a Sock Näägl drin vaiad!', '', '', '', 'Wienerisches aus Musik, Kunst, Kultur & Medien', 'Da bröselt’s im Lautsprecher, als hätt sich ein Sack Nägel drin verirrt!', '[{"kategorie": "wörtlich", "text": "\"Da rauscht’s im Lautsprecher, als hätt sich ein Sack Nägel drin verirrt!\"  2. Im Lautsprecher knistert''s, als ob da drin grad jemand Popcorn frisst!  3. Im Lautsprecher grummelt''s, als hätt'' da drin grad jemand ein Lagerfeuer angezündet!"}]'::jsonb, ''),
