  ('waunn-i-mit-dia-featig-bin-schreibst-di-breesal', 'Waunn I mit dia featig bin, schreibst di Breesal!', '', '', '', 'Wiener Gaunersprache', 'Wenn ich mit dir fertig bin, schreibst du dich ''Bröserl''!', '[{"kategorie": "wörtlich", "text": "\"Wenn ich dich fertigmache, kannst du deinen Namen aus eigenen Krümelchen schreiben!\"  2. Wenn ich dich verhaue, werden von dir nur Bröselchen übrig bleiben!  3. Wenn ich dir eine Abreibung verpasse, wirst du nur noch Staub sein!"}]'::jsonb, ''),
  ('brunz-di-ned-au', 'Brunz di ned au!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Brunz dich nicht an!', '[{"kategorie": "wörtlich", "text": "\"Mach dir nicht in die Hose!\"  2. Jetzt reiß dich zusammen!  3. Bleib cool!  4. Nur keine Panik!"}]'::jsonb, ''),
