  ('du-inkontinenta-fischlada-brunzschaeaedl', 'Du inkontinenta, fischlada Brunzschäädl!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Du inkontinenter, fischelnder Brunzschädel!', '[{"kategorie": "wörtlich", "text": "\"Du inkontinenter, fischelnder Suffkopf!\"  2. \"Du triefender, durchgeweichter Suffbolzen!\"  3. \"Du versiffte, vollgesoffene Rauschbirne!\""}]'::jsonb, ''),
  ('dea-brunzschaeaedl-saufd-in-wei-wiara-himbawossa', 'Dea Brunzschäädl saufd in Wei wiara Himbawossa!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Der Brunzschädel säuft den Wein wie Himbeerwasser!', '[{"kategorie": "wörtlich", "text": "\"Dieser Suffkopf trinkt den Wein wie Himbeerwasser!\"  2. \"Dieser Vollsuff kippt den Wein runter, als wär''s ''ne Limonade!\"  3. \"Der Brunzschädel kippt den Wein runter wie Brunnenwasser!\""}]'::jsonb, ''),
  ('dea-brunzschaeaedl-is-efta-aum-heisl-ois-aun-da-schaunk', 'Dea Brunzschäädl is efta aum Heisl ois aun da Schaunk!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Dieser Brunzschädel ist öfter am Häusl als an der Schank!', '[{"kategorie": "wörtlich", "text": "\"Dieser Pinkelkopf ist öfter am Klo als an der Schank!\"  2. Dieser Dauerpinkler steht mehr am Pissoir als an der Schank!  3. Dieser Inkontinenzler sollte sich sein Bier aufs Klo mitnehmen!"}]'::jsonb, ''),
  ('dea-dauabrunza-is-efta-aum-heisl-ois-aun-da-schaunk', 'Dea Dauabrunza is efta aum Heisl ois aun da Schaunk!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Dieser Dauerbrunzer ist öfter am Häusl als an der Schank!', '[{"kategorie": "wörtlich", "text": "\"Dieser Dauerpinkler ist öfter am Klo als an der Schank!\"  2. Dieser Brunzschädl steht mehr am Pissoir als an der Schank!  3. Dieser Inkontinenzler sollte sich sein Bier aufs Klo mitnehmen!"}]'::jsonb, ''),
  ('dea-inkontinenzla-is-efta-aum-heisl-ois-aun-da-schaunk', 'Dea Inkontinenzla is efta aum Heisl ois aun da Schaunk!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Dieser Inkontinenzler ist öfter am Häusl als an der Schank!', '[{"kategorie": "wörtlich", "text": "\"Dieser Inkontinenzler ist öfter am Klo als an der Schank!\"  2. Dieser Brunzschädl steht mehr am Pissoir als an der Schank!  3. Dieser Dauerpinkler sollte sich sein Bier aufs Klo mitnehmen!"}]'::jsonb, ''),
  ('a-klassa-bua', 'A klassa Bua!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Ein klasser Bub!', '[{"kategorie": "wörtlich", "text": "\"Ein klasser Kerl!\"  2. Ein toller Bursche!  3. Ein coloer Typ!  4. Ein Hammerkerl! (siehe [[Bua]])"}]'::jsonb, ''),
  ('da-bua-is-in-knecht-untaschdoeoed-und-kriagd-kaum-an-loon', 'Da Bua is in Knecht untaschdööd und kriagd kaum an Loon!', '', '', '', 'Wiener Wörter mit schillernder Geschichte', 'Der Bub ist dem Knecht unterstellt und bekommt kaum Lohn!', '[{"kategorie": "wörtlich", "text": "\"Der Bub dient unter dem Knecht und erhält dafür kaum einen Kreuzer!\"  2. Der Knabe rangiert selbst unter dem Knecht – und wird mit spärlichem Lohn abgespeist!  3. Der Trossjunge darf dem Knecht die Schuhe putzen – und kriegt dafür den Dreck vom Teller!"}]'::jsonb, ''),
  ('auf-mein-buam-bin-i-schdoiz-waeu-immahin-waassa-wo-vuan-und-hintn-is', 'Auf mein Buam bin I schdoiz - wäu immahin waassa, wo vuan und hintn is!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Auf meinen Buben bin ich stolz - denn immerhin weiß er, wo vorn und hinten ist!', '[{"kategorie": "wörtlich", "text": "\"Auf meinen Jungen bin ich stolz - immerhin kennt er den Unterschied zwischen vorne und hinten!\"  2. Mein Kleiner ist ein Genie – er weiß sogar, wo der Kopf und wo der Hintern ist!  3. Mein Bub ist kein Überflieger - aber [[Gsicht]] und [[Oasch]] verwechselt er nimmer!"}]'::jsonb, ''),
  ('unsare-buama-weans-schbueue-gwinnan', 'Unsare Buama weans Schbüü gwinnan!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Unsere Buben werden das Spiel gewinnen!', '[{"kategorie": "wörtlich", "text": "\"Unsere Jungs werden das Spiel gewinnen!\"  2. Unsere Kicker werden den Sieg holen!  3. Unsere Jungs werden den Gegner wegballern!"}]'::jsonb, ''),
